#include "ultrapool/core.hpp"
#include <cstdio>
#include <cstdlib>
using namespace up;
namespace {
unsigned checks=0;
void verify(bool value,const char* why){++checks;if(!value){std::fprintf(stderr,"FAIL SHOP TRANSFORM: %s\n",why);std::exit(1);}}
void fixture(Game& g){g.phase=Phase::Shop;g.round=3;g.shop_sets[0]=ItemSet::CLASSIC;g.set_run_seed(12345678);g.inventory[0]=default_item(id_of(BallKey::INCUBATOR),2);g.inventory[0].score=5;g.inventory[1]=default_item(id_of(BallKey::SHARK_PLUSH),2);g.inventory[2]=default_item(id_of(BallKey::POTION),2);g.inventory_count=3;}
}
unsigned shop_transform_tests(){
 {Game g;g.phase=Phase::Shop;g.snack_bar=true;g.snack_tickets=2;g.money=19;g.round=3;g.shop_sets[0]=ItemSet::CLASSIC;g.snack_random.reset(12345);g.stock_snacks();const auto stock=g.snack_offers;const auto state=g.snack_random.state;Input square;square.inspect=true;g.input(square,.016f);verify(g.snack_offers==stock && g.snack_random.state==state && g.snack_tickets==2 && g.money==19,"hidden original debug reroll is not exposed as player Square action");}

 {Game g;fixture(g);g.shop_sets[0]=ItemSet::TECH;g.inventory[0]=g.inventory[2]=OwnedBall();g.inventory_count=1;g.offers[0]=id_of(BallKey::SCRAP);g.offer_items[0]=default_item(id_of(BallKey::SCRAP),2);g.offer_items[0].mixed_with=id_of(BallKey::INCUBATOR);g.offer_items[0].score=5;g.run_shop_event(Signal::Upgrade,15);verify(g.offers[0]!=id_of(BallKey::SCRAP) && g.offer_item(0).id==g.offers[0] && g.offer_item(0).mixed_with==id_of(BallKey::INCUBATOR),"offered Scrap replacement updates both visible identity and mutable stock atomically");verify(g.offer_item(0).score==18,"offered Scrap preserves transformation reactions on its mutable value");}

 for(bool secondary:{false,true}){Game g;g.phase=Phase::Shop;g.set_run_seed(30);g.inventory[0]=default_item(id_of(secondary?BallKey::INCUBATOR:BallKey::CATERPILLAR),5);g.inventory[0].mixed_with=id_of(secondary?BallKey::CATERPILLAR:BallKey::INCUBATOR);g.inventory[0].score=1;g.inventory[1]=default_item(id_of(BallKey::SHARK_PLUSH),2);g.shop_buff(0,2);verify((secondary?g.inventory[0].mixed_with:g.inventory[0].id)==id_of(BallKey::BUTTERFLY),"successful shop Caterpillar roll replaces the correct mixed side");verify(g.inventory[0].score==24 && g.inventory[1].score==4,"shop transformation applies old Incubator and Shark once without buffing whole roster");verify(g.profile.has("transform_caterpillar"),"unseeded shop Caterpillar transformation unlocks achievement");}
 {Game g;g.phase=Phase::Shop;g.set_run_seed(1);g.inventory[0]=default_item(id_of(BallKey::CATERPILLAR),5);g.inventory[0].score=1;g.shop_buff(0,2);verify(g.inventory[0].id==id_of(BallKey::CATERPILLAR) && g.inventory[0].score==3,"failed shop chance preserves identity and incoming gain");g.set_run_seed(30,true);g.shop_buff(0,1);verify(g.inventory[0].id==id_of(BallKey::BUTTERFLY) && !g.profile.has("transform_caterpillar"),"custom-seeded shop transformation grants no achievement");}
 {Game g;g.phase=Phase::Shop;g.set_run_seed(30);g.offers[0]=id_of(BallKey::CATERPILLAR);g.offer_items[0]=default_item(id_of(BallKey::CATERPILLAR),5);g.offer_items[0].score=1;g.shop_buff(15,2);verify(g.offers[0]==id_of(BallKey::BUTTERFLY) && g.offer_item(0).score==3 && !g.inventory[0].id,"offered Caterpillar transformation updates visible stock only");}

 {Game g;g.phase=Phase::Shop;g.inventory[0]=default_item(id_of(BallKey::BUSH),2);g.inventory[0].score=5;g.shop_buff(0,3);verify(g.inventory[0].score==10,"shop Bush adds its level once after incoming positive buff");g.inventory[1]=default_item(id_of(BallKey::GAIA));g.inventory[0].score=5;g.shop_buff(0,3);verify(g.inventory[0].score==12,"Gaia applies to both incoming and non-chaining Bush gains");}
 {Game g;g.phase=Phase::Shop;g.inventory[0]=default_item(id_of(BallKey::ANTIMATTER));g.inventory[0].score=10;g.shop_buff(0,3);verify(g.inventory[0].score==7,"shop Antimatter reverses twice the effective incoming gain");g.shop_buff(0,-2);verify(g.inventory[0].score==5,"negative shop change does not trigger positive buff reactions");}
 for(bool reverse:{false,true}){Game g;g.phase=Phase::Shop;g.inventory[0]=default_item(id_of(reverse?BallKey::ANTIMATTER:BallKey::BUSH),2);g.inventory[0].mixed_with=id_of(reverse?BallKey::BUSH:BallKey::ANTIMATTER);g.inventory[0].score=1;g.shop_buff(0,3);verify(g.inventory[0].score==(reverse?3:1),"mixed shop Bush/Antimatter preserves component order and per-change floor");}
 {Game g;g.phase=Phase::Shop;g.inventory[0]=default_item(id_of(BallKey::MOSS),2);g.inventory[0].score=1;g.inventory[1]=default_item(id_of(BallKey::BUSH),2);g.inventory[1].score=1;g.offers[0]=id_of(BallKey::BUSH);g.offer_items[0]=default_item(id_of(BallKey::BUSH));g.shop_buff(0,5);verify(g.inventory[0].score==6 && g.inventory[1].score==5,"shop Moss transfers ceil-scaled gain and receiving Bush reacts");verify(g.offer_item(0).score==ball_info(id_of(BallKey::BUSH)).base_score,"shop Moss targets owned build rather than offered balls");g.inventory[0].score=g.inventory[1].score=1;g.inventory[1].id=id_of(BallKey::MOSS);g.shop_buff(0,5);verify(g.inventory[0].score==6 && g.inventory[1].score==3,"Moss-marked shop gain cannot bounce between two Moss balls");}

 for(bool mixed:{false,true}){Game g;fixture(g);if(mixed)g.inventory[0].mixed_with=id_of(BallKey::BRICKS);verify(g.sell(2),"Potion sale succeeds");verify(g.inventory[0].id!=id_of(BallKey::INCUBATOR) && g.inventory[0].score==19,"Potion dispatches old Incubator, Shark Plush and sold-level buff exactly once");verify(!g.inventory[2].id && g.inventory[1].score==4,"Potion consumes only sold item and leaves observing Shark value unchanged");}
 for(bool secondary:{false,true}){Game g;fixture(g);g.shop_sets[0]=ItemSet::TECH;g.inventory[2]=OwnedBall();g.inventory_count=2;g.inventory[0].id=id_of(secondary?BallKey::INCUBATOR:BallKey::SCRAP);g.inventory[0].mixed_with=id_of(secondary?BallKey::SCRAP:BallKey::INCUBATOR);g.run_shop_event(Signal::Upgrade,0);verify(g.inventory[0].score==18 && g.scrap_rolls==1,"Scrap upgrade dispatches one old Incubator and one Shark reaction");verify(g.inventory[0].id!=id_of(BallKey::SCRAP) && g.inventory[0].mixed_with!=id_of(BallKey::SCRAP),"eligible Tech pool actually replaces the upgraded Scrap component");verify((g.inventory[0].id==id_of(BallKey::INCUBATOR))==secondary,"Scrap transform preserves the other component side");}
 {Game g;fixture(g);g.inventory[0]=OwnedBall();g.inventory_count=2;verify(g.sell(2) && g.inventory[1].score==4,"Potion with empty front does not notify transform listeners");}
 std::printf("Shop transformation checks: %u\n",checks);return checks;
}

